	border-bottom: 1px solid var(--color-border);
	box-sizing: border-box;
}
.action-row--system-planning[data-v-ac92609e] {
	height: 76px;
	background: rgba(59, 130, 246, 0.03);
}
.action-row--phase-header[data-v-ac92609e] {
	background: var(--color-background-hover);
}
.action-row__locked-hint[data-v-ac92609e],
.action-row__deck-hint[data-v-ac92609e] {
	color: var(--color-text-lighter);
	display: flex;
	align-items: center;
	justify-content: center;
	opacity: 0.7;
}
.action-row__deck-hint[data-v-ac92609e] {
	color: var(--color-primary-element);
}

/* Footer / Phase Jumper */
.timeline-v2__footer[data-v-ac92609e] {
	padding: 16px 24px;
	background: var(--color-background-dark);
}
.phase-jumper[data-v-ac92609e] {
	display: flex;
	align-items: center;
	gap: 16px;
}
.jumper-label[data-v-ac92609e] {
	font-size: 13px;
	font-weight: 700;
	color: var(--color-text-maxcontrast);
}
.jumper-chips[data-v-ac92609e] {
	display: flex;
	gap: 8px;
	flex-wrap: wrap;
}
.phase-chip[data-v-ac92609e] {
	padding: 6px 14px;
	border-radius: 12px;
	font-size: 12px;
	font-weight: 600;
	border: 1px solid var(--color-border);
	background: var(--color-main-background);
	color: var(--color-main-text);
	cursor: pointer;
	transition: all 0.2s ease;
}
.phase-chip[data-v-ac92609e]:hover {
	border-color: var(--phase-color);
	background: var(--color-background-hover);
}

/* Phase Form / Modal */
.phase-form[data-v-ac92609e] {
	padding: 32px;
}
.phase-form__header[data-v-ac92609e] {
	margin-bottom: 24px;
}
.phase-form__header h3[data-v-ac92609e] {
	margin: 0;
	font-size: 22px;
}
.phase-form__header p[data-v-ac92609e] {
	margin: 4px 0 0;
	color: var(--color-text-maxcontrast);
}
.phase-form__content[data-v-ac92609e] {
	display: flex;
	flex-direction: column;
	gap: 20px;
}
.form-select[data-v-ac92609e] {
	width: 100%;
	height: 44px;
	border-radius: var(--border-radius-large);
	border: 1px solid var(--color-border);
	background: var(--color-main-background);
	color: var(--color-main-text);
	padding: 0 12px;
	font-size: 14px;
}
.form-field--checkbox[data-v-ac92609e] {
	display: flex;
	align-items: flex-end;
}
.form-checkbox[data-v-ac92609e] {
	display: inline-flex;
	align-items: center;
	gap: 10px;
	height: 44px;
	padding: 0 10px;
	border: 1px solid var(--color-border);
	border-radius: var(--border-radius-large);
	background: var(--color-main-background);
}
.form-checkbox input[data-v-ac92609e] {
	width: 16px;
	height: 16px;
}
.form-label[data-v-ac92609e] {
	display: block;
	font-size: 13px;
	font-weight: 700;
	margin-bottom: 8px;
	color: var(--color-text-maxcontrast);
}
.form-row[data-v-ac92609e] {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 16px;
}
.color-grid[data-v-ac92609e] {
	display: flex;
	gap: 10px;
	flex-wrap: wrap;
}
.color-swatch[data-v-ac92609e] {
	width: 36px;
	height: 36px;
	border-radius: 10px;
	border: 2px solid transparent;
	cursor: pointer;
	transition: transform 0.2s ease;
}
.color-swatch[data-v-ac92609e]:hover {
	transform: scale(1.1);
}
.color-swatch.active[data-v-ac92609e] {
	border-color: var(--color-main-text);
	box-shadow: 0 0 0 2px var(--color-main-background), 0 0 0 4px var(--color-primary-element);
}
.phase-form__footer[data-v-ac92609e] {
	margin-top: 32px;
	display: flex;
	justify-content: flex-end;
	gap: 12px;
}
@media (max-width: 900px) {
.gantt-v2[data-v-ac92609e], .gantt-v2--admin[data-v-ac92609e] {
		grid-template-columns: 1fr;
}
.gantt-v2__sidebar[data-v-ac92609e] { border-right: none;
}
.gantt-v2__status[data-v-ac92609e] { border-left: none;
}
.gantt-v2__actions[data-v-ac92609e] { border-left: none;
}
}
