  overflow-wrap: anywhere;
}
.insights-panel__content[data-v-5b7fc34e] {
  container-type: inline-size;
  min-width: 0;
  padding: var(--spacing-lg, 24px);
}

/* ─── Sub-section Title ─── */
.insights-panel__resources[data-v-5b7fc34e] {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.insights-panel__resource[data-v-5b7fc34e] {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 12px 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-el, 8px);
  background: var(--bg-subtle);
}
.insights-panel__resource-value[data-v-5b7fc34e] {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.15;
  color: var(--color-text-primary);
  font-variant-numeric: tabular-nums;
}
.insights-panel__resource-label[data-v-5b7fc34e] {
  font-size: 12px;
  color: var(--color-text-secondary);
}
