  color: var(--color-text-muted);
}
.insights-panel__section-title[data-v-5b7fc34e] {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-secondary, #6b7280);
  font-family: "Space Grotesk", system-ui, sans-serif;
