  background: var(--accent-bg);
  color: var(--accent-strong);
  padding: 1px 7px;
  border-radius: 8px;
  margin-left: 2px;
}

/* ─── Controls in a section title row ───
   Capacity is the first section to carry any. The title row is uppercase and
   letter-spaced and both inherit, so a button dropped in reads "REFRESH" at
   0.03em — reset them here rather than on each control. */
.insights-panel__section-actions[data-v-5b7fc34e] {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: var(--spacing-sm, 8px);
  text-transform: none;
  letter-spacing: normal;
}
.insights-panel__section-meta[data-v-5b7fc34e] {
  font-size: var(--iz-fs-xs);
  font-weight: 500;
  color: var(--color-text-muted);
  font-variant-numeric: tabular-nums;
}

/* ─── Project defaults section ─── */
.insights-panel__settings-block + .insights-panel__settings-block[data-v-5b7fc34e] {
  margin-top: var(--spacing-lg, 22px);
  padding-top: var(--spacing-lg, 22px);
  border-top: 1px dashed var(--bg-subtle);
}
.insights-panel__settings-sub[data-v-5b7fc34e] {
  margin: 0 0 var(--spacing-sm, 8px);
  font-size: var(--iz-fs-sm);
  font-weight: 600;
  color: var(--color-text-primary);
}

/* Embedded panels now respond to the available detail width, including
   desktop layouts narrowed by the section navigation. */
@container (max-width: 620px) {
.insights-panel__section[data-v-5b7fc34e] .org-panel__details,
  .insights-panel__section[data-v-5b7fc34e] .sub-panel__details,
  .insights-panel__section[data-v-5b7fc34e] .sub-panel__meters,
  .insights-panel__section[data-v-5b7fc34e] .storage-monitor__lists {
    grid-template-columns: minmax(0, 1fr);
}
.insights-panel__section[data-v-5b7fc34e] .org-panel__detail-row,
  .insights-panel__section[data-v-5b7fc34e] .sub-panel__detail-row {
    flex-wrap: wrap;
    gap: var(--spacing-sm, 8px);
    overflow-wrap: anywhere;
}
}
@media (max-width: 768px) {
.insights-panel__body[data-v-5b7fc34e] { grid-template-columns: minmax(0, 1fr);
}
.insights-panel__nav[data-v-5b7fc34e] {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    border-right: none;
    border-bottom: 1px solid var(--color-border);
}
.insights-panel__content[data-v-5b7fc34e] { padding: var(--spacing-md, 16px);
}
.insights-panel__section-title[data-v-5b7fc34e],
  .insights-panel__section-actions[data-v-5b7fc34e] { flex-wrap: wrap;
}
}
