600;\n  background: var(--accent-bg);\n  color: var(--accent-strong);\n  padding: 1px 7px;\n  border-radius: 8px;\n  margin-left: 2px;\n}\n\n/* ─── Controls in a section title row ───\n   Capacity is the first section to carry any. The title row is uppercase and\n   letter-spaced and both inherit, so a button dropped in reads \"REFRESH\" at\n   0.03em — reset them here rather than on each control. */\n.insights-panel__section-actions {\n  margin-left: auto;\n  display: flex;\n  align-items: center;\n  gap: var(--spacing-sm, 8px);\n  text-transform: none;\n  letter-spacing: normal;\n}\n\n.insights-panel__section-meta {\n  font-size: var(--iz-fs-xs);\n  font-weight: 500;\n  color: var(--color-text-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n/* ─── Project defaults section ─── */\n.insights-panel__settings-block + .insights-panel__settings-block {\n  margin-top: var(--spacing-lg, 22px);\n  padding-top: var(--spacing-lg, 22px);\n  border-top: 1px dashed var(--bg-subtle);\n}\n\n.insights-panel__settings-sub {\n  margin: 0 0 var(--spacing-sm, 8px);\n  font-size: var(--iz-fs-sm);\n  font-weight: 600;\n  color: var(--color-text-primary);\n}\n\n/* Embedded panels now respond to the available detail width, including\n   desktop layouts narrowed by the section navigation. */\n@container (max-width: 620px) {\n  .insights-panel__section ::v-deep .org-panel__details,\n  .insights-panel__section ::v-deep .sub-panel__details,\n  .insights-panel__section ::v-deep .sub-panel__meters,\n  .insights-panel__section ::v-deep .storage-monitor__lists {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .insights-panel__section ::v-deep .org-panel__detail-row,\n  .insights-panel__section ::v-deep .sub-panel__detail-row {\n    flex-wrap: wrap;\n    gap: var(--spacing-sm, 8px);\n    overflow-wrap: anywhere;\n  }\n}\n\n@media (max-width: 768px) {\n  .insights-panel__body { grid-template-columns: minmax(0, 1fr); }\n  .insights-panel__nav {\n    display: grid;\n    grid-template-colum